ALTER TABLE inventory_batch ADD version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE inventory_batch ADD CONSTRAINT ck_inventory_batch_version_non_negative CHECK (version >= 0);
CREATE TABLE inventory_transaction (id BIGINT GENERATED BY DEFAULT AS IDENTITY, transaction_type VARCHAR(16) NOT NULL, ingredient_id BIGINT NOT NULL, amount NUMERIC NOT NULL, unit_code VARCHAR(16) NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT pk_inventory_transaction PRIMARY KEY(id), CONSTRAINT fk_inventory_transaction_ingredient FOREIGN KEY(ingredient_id) REFERENCES ingredient(id), CONSTRAINT ck_inventory_transaction_type CHECK(transaction_type='CONSUME'), CONSTRAINT ck_inventory_transaction_amount CHECK(amount>0), CONSTRAINT ck_inventory_transaction_unit CHECK(unit_code IN ('g','ml','piece')));
CREATE TABLE inventory_transaction_allocation (transaction_id BIGINT NOT NULL, position INTEGER NOT NULL, batch_id BIGINT NOT NULL, amount NUMERIC NOT NULL, before_amount NUMERIC NOT NULL, after_amount NUMERIC NOT NULL, CONSTRAINT pk_inventory_transaction_allocation PRIMARY KEY(transaction_id,position), CONSTRAINT uq_inventory_transaction_batch UNIQUE(transaction_id,batch_id), CONSTRAINT fk_allocation_transaction FOREIGN KEY(transaction_id) REFERENCES inventory_transaction(id), CONSTRAINT fk_allocation_batch FOREIGN KEY(batch_id) REFERENCES inventory_batch(id), CONSTRAINT ck_allocation_position CHECK(position>0), CONSTRAINT ck_allocation_amount CHECK(amount>0), CONSTRAINT ck_allocation_before CHECK(before_amount>=0), CONSTRAINT ck_allocation_after CHECK(after_amount>=0), CONSTRAINT ck_allocation_arithmetic CHECK(before_amount=amount+after_amount));
